#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""מפחית עומס על חשבונות טלגרם: ניסיון חוזר ברמת הבלוק, ואימות משיכה
אמיתית לפני החזרת בוט לרוטציה.

בטוח להרצה חוזרת. גיבוי + בדיקת קומפילציה + שחזור אוטומטי בכשל.
"""
import pathlib, py_compile, shutil, sys, time

P = pathlib.Path("/opt/zovex-bot/main.py")
s = P.read_text(encoding="utf-8")
done = []

if "_bot_can_download" in s and "_get_block" in s:
    print("כבר מוחל — אין מה לעשות.")
    sys.exit(0)

PAIRS = [('async def _band_fetch(session: Session, location, lo: int, hi: int) -> bytes:\n    """מושך בדיוק [lo, hi] דרך חיבור media יחיד ומחזיר את הבייטים."""\n    out = bytearray()\n    offset = (lo // MEDIA_CHUNK) * MEDIA_CHUNK\n    produced = offset\n    while produced <= hi:\n        try:\n            r = await session.invoke(functions.upload.GetFile(\n                location=location, offset=offset, limit=MEDIA_CHUNK, precise=False))\n        except FloodWait as e:\n            # קריטי: הגרסה הקודמת לא תפסה FloodWait כאן כלל — כל האטה של טלגרם\n            # הפילה את הרצועה, ובעקבותיה נזרקה כל בריכת החיבורים (thrash) והסרט\n            # נתקע. FloodWait קצר: ישנים ומנסים שוב; ארוך: זורקים בשקט (fallback).\n            if e.value > MEDIA_BAND_FLOOD_CAP:\n                raise\n            await asyncio.sleep(e.value + 0.5)\n            continue\n        chunk = getattr(r, "bytes", b"")\n        if not chunk:\n            break\n        c_start, c_end = produced, produced + len(chunk)\n        a = max(lo, c_start) - c_start\n        b = min(hi + 1, c_end) - c_start\n        if a < b:\n            out += chunk[a:b]\n        produced = c_end\n        offset = produced\n        if len(chunk) < MEDIA_CHUNK:\n            break\n    return bytes(out)\n\n\n', '# ניסיונות חוזרים ברמת הבלוק הבודד. עד היום בלוק שנכשל הפיל את כל הרצועה,\n# ואיתה את החלון, ואיתו את בריכת החיבורים — ואז הבקשה נפלה למסלול שפותח\n# session שלם לכל משיכה. כלומר תקלה רגעית אחת ייצרה עשרות בקשות נוספות מול\n# טלגרם, וזה בדיוק מה שהעמיס את החשבונות עד שהם נחנקו. ניסיון חוזר על אותו\n# חיבור, עם השהיה שמכפילה את עצמה, עולה בקשה אחת ולא מפיל כלום.\nBLOCK_RETRIES = int(os.environ.get("STREAM_BLOCK_RETRIES", "4"))\nBLOCK_BACKOFF_START = float(os.environ.get("STREAM_BLOCK_BACKOFF", "0.1"))\nBLOCK_BACKOFF_MAX = float(os.environ.get("STREAM_BLOCK_BACKOFF_MAX", "8"))\n\n\nasync def _get_block(session: Session, location, offset: int, limit: int) -> bytes:\n    """מושך בלוק בודד, עם ניסיונות חוזרים והשהיה מכפילה.\n\n    FloodWait קצר: ישנים בדיוק כמה שטלגרם ביקש. שגיאת חיבור רגעית: משהים\n    ומנסים שוב על אותו חיבור. רק אחרי שכל הניסיונות נכשלו הכשל עולה למעלה.\n    """\n    backoff = BLOCK_BACKOFF_START\n    last = None\n    for attempt in range(max(1, BLOCK_RETRIES)):\n        try:\n            r = await session.invoke(functions.upload.GetFile(\n                location=location, offset=offset, limit=limit, precise=False))\n            return getattr(r, "bytes", b"")\n        except FloodWait as e:\n            # FloodWait ארוך אינו האטה רגעית — עדיף לוותר ולתת לחלון ליפול\n            # לבוט אחר מאשר להחזיק את הצופה תקוע.\n            if e.value > MEDIA_BAND_FLOOD_CAP:\n                raise\n            await asyncio.sleep(e.value + 0.5)\n            continue\n        except (OSError, ConnectionError, EOFError, asyncio.TimeoutError) as e:\n            last = e\n            if attempt == BLOCK_RETRIES - 1:\n                raise\n            await asyncio.sleep(backoff)\n            backoff = min(backoff * 2, BLOCK_BACKOFF_MAX)\n    if last is not None:\n        raise last\n    return b""\n\n\nasync def _band_fetch(session: Session, location, lo: int, hi: int) -> bytes:\n    """מושך בדיוק [lo, hi] דרך חיבור media יחיד ומחזיר את הבייטים."""\n    # בלוק של מגהבייט — המקסימום שהפרוטוקול מרשה. בלוק קטן יותר חוסך בייטים\n    # אבל מכפיל את מספר הבקשות, והמשאב שנגמר לנו הוא בקשות-לשנייה לכל חשבון\n    # (נמדד ~15-20), לא רוחב פס. נבדק: 3MB בבלוקים של 256KB = 13 בקשות מול 4.\n    block = MEDIA_CHUNK\n    out = bytearray()\n    offset = (lo // block) * block\n    produced = offset\n    while produced <= hi:\n        chunk = await _get_block(session, location, offset, block)\n        if not chunk:\n            break\n        c_start, c_end = produced, produced + len(chunk)\n        a = max(lo, c_start) - c_start\n        b = min(hi + 1, c_end) - c_start\n        if a < b:\n            out += chunk[a:b]\n        produced = c_end\n        offset = produced\n        if len(chunk) < block:\n            break\n    return bytes(out)\n\n\n', 'ניסיון חוזר ברמת הבלוק'), ('async def revive_stream_pool():', '_probe_msg_id_cache: list = []\n\n\ndef _probe_msg_id():\n    """מזהה הודעה כלשהי מהערוץ, לבדיקת משיכה אמיתית. נשלף פעם אחת."""\n    if _probe_msg_id_cache:\n        return _probe_msg_id_cache[0]\n    for e in load_content():\n        m = re.search(r"/stream/-?\\d+/(\\d+)", str(e.get("video_url") or ""))\n        if m:\n            _probe_msg_id_cache.append(int(m.group(1)))\n            return _probe_msg_id_cache[0]\n    return None\n\n\nasync def _bot_can_download(bot) -> bool:\n    """האם הבוט באמת מסוגל למשוך בייטים מטלגרם.\n\n    קריטי: `get_me()` אינו בדיקה מספקת. חשבון שטלגרם חנק *להורדות* עונה\n    ל-get_me מצוין — הוא לא חסום, רק מוגבל. לכן הבדיקה הזולה הכריזה על 12\n    חשבונות חנוקים כ"בריאים" כל שתי דקות, איפסה להם את דרגת העונש והחזירה\n    אותם לרוטציה — והעונש המתגבר (30ש\' → 2ד\' → 8ד\' → 30ד\') לא הספיק להתכנס\n    לפני שאופס שוב. התוצאה: רוב הבחירות המשיכו לנחות על בוטים מתים.\n\n    כאן מושכים 64KB אמיתיים. זו בדיוק היכולת שאכפת לנו ממנה.\n    """\n    msg_id = _probe_msg_id()\n    if not STREAM_CHANNEL_ID or msg_id is None:\n        return False\n    try:\n        msg = await asyncio.wait_for(\n            _get_bot_msg(bot, STREAM_CHANNEL_ID, msg_id), timeout=15)\n        media = msg and (msg.video or msg.audio or msg.document or msg.video_note)\n        if not media:\n            return False\n        dc_id, location = _file_location(media)\n        sessions, _gen = await get_media_session_pool_gen(\n            bot["client"], bot["name"], dc_id, 1, block=True)\n        if not sessions:\n            return False\n        want = 64 * 1024\n        data = await asyncio.wait_for(\n            _band_fetch(sessions[0], location, 0, want - 1), timeout=20)\n        return len(data) >= want\n    except Exception:\n        return False\n\n\nasync def revive_stream_pool():', 'בדיקת משיכה אמיתית (_bot_can_download)'), ('            name = b["name"]\n            try:\n                # קודם בדיקה זולה: אולי הוא כבר התאושש מעצמו וחבל להפיל session.\n                await asyncio.wait_for(b["client"].get_me(), timeout=10)\n                b["chokes"] = 0\n                b["fails"] = 0\n                b["cooldown_until"] = 0.0\n                log.info("✅ %s התאושש — חזר לרוטציה", name)\n                continue\n            except Exception:\n                pass\n            log.warning("♻️ %s תקוע — מרים session מחדש", name)\n', '            name = b["name"]\n            # קודם: האם הוא כבר מסוגל למשוך? אם כן, חבל להפיל לו session.\n            if await _bot_can_download(b):\n                b["chokes"] = 0\n                b["fails"] = 0\n                b["cooldown_until"] = 0.0\n                log.info("✅ %s מושך בייטים שוב — חזר לרוטציה", name)\n                continue\n            log.warning("♻️ %s לא מושך בייטים — מרים session מחדש", name)\n', 'החייאה: אימות לפני החזרה לרוטציה'), ('                b["peer_ok"] = await _resolve_peer(b["client"], name)\n                for k in [k for k in _bot_msg_cache if k[0] == name]:\n                    _bot_msg_cache.pop(k, None)\n                b["chokes"] = 0\n                b["fails"] = 0\n                b["speed"] = None\n                b["cooldown_until"] = 0.0\n                log.info("✅ %s הורם מחדש וחזר לרוטציה", name)\n', '                b["peer_ok"] = await _resolve_peer(b["client"], name)\n                for k in [k for k in _bot_msg_cache if k[0] == name]:\n                    _bot_msg_cache.pop(k, None)\n                # session טרי אינו ערובה למשיכה: חשבון חנוק מתחבר בשמחה\n                # ורק ההורדה שלו חסומה. בלי האימות הזה הוא היה חוזר לרוטציה\n                # וגובה timeout מלא מכל חלון שנוחת עליו, שוב ושוב.\n                if not await _bot_can_download(b):\n                    log.warning("⚠️ %s עלה אבל עדיין לא מושך — נשאר מודח", name)\n                else:\n                    b["chokes"] = 0\n                    b["fails"] = 0\n                    b["speed"] = None\n                    b["cooldown_until"] = 0.0\n                    log.info("✅ %s הורם מחדש ומושך — חזר לרוטציה", name)\n', 'החייאה: אימות גם אחרי הרמת session')]

for old, new, label in PAIRS:
    c = s.count(old)
    if c != 1:
        print("### '%s': נמצאו %d מופעים במקום 1 — לא שונה כלום ###" % (label, c))
        sys.exit(1)
for old, new, label in PAIRS:
    s = s.replace(old, new, 1)
    done.append(label)

bak = P.with_name("main_before_calm_%d.py" % time.time())
shutil.copy2(P, bak)
P.write_text(s, encoding="utf-8")
try:
    py_compile.compile(str(P), doraise=True)
except Exception as e:
    shutil.copy2(bak, P)
    print("### הקומפילציה נכשלה — שוחזר הגיבוי ###")
    print(e); sys.exit(1)
print("הוחל:")
for d in done: print("   + " + d)
print("\n   גיבוי: " + bak.name)
print("\n   עכשיו:  sudo systemctl restart zovex-bot")
